#!/usr/bin/env python3
"""Emit one systemd and kernel Audit health snapshot as compact JSON."""
import json
import os
import shutil
import subprocess
import time

SCHEMA = 1
COMMAND_PATH = "/usr/sbin:/usr/bin:/sbin:/bin"
SYSTEMD_PROPERTIES = (
    "LoadState,ActiveState,SubState,Result,MainPID,UnitFileState"
)
AUDIT_INTEGER_FIELDS = {
    "enabled",
    "failure",
    "pid",
    "rate_limit",
    "backlog_limit",
    "lost",
    "backlog",
    "backlog_wait_time",
    "backlog_wait_time_actual",
}


def run(command, *arguments):
    return subprocess.run(
        [command, *arguments],
        check=False,
        capture_output=True,
        text=True,
        timeout=15,
        env={"PATH": COMMAND_PATH, "LC_ALL": "C"},
    )


def read_text(path, default="unknown"):
    try:
        with open(path, "r", encoding="ascii") as handle:
            return handle.read().strip()
    except OSError:
        return default


def integer(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def parse_key_value(text, separator="="):
    values = {}
    for line in text.splitlines():
        key, found, value = line.partition(separator)
        if found:
            values[key.strip()] = value.strip()
    return values


def parse_audit_status(text):
    values = {}
    for line in text.splitlines():
        columns = line.split()
        if len(columns) >= 2:
            key = columns[0]
            value = columns[1]
            values[key] = integer(value) if key in AUDIT_INTEGER_FIELDS else value
    return values


def main():
    event = {
        "record_type": "auditd_health",
        "collector_schema": SCHEMA,
        "sample_epoch": int(time.time()),
        "boot_id": read_text("/proc/sys/kernel/random/boot_id"),
        "boot_uptime_seconds": integer(read_text("/proc/uptime", "0").split()[0].split(".")[0]),
        "service_unit": "auditd.service",
    }
    errors = []
    systemctl = shutil.which("systemctl", path=COMMAND_PATH)
    auditctl = shutil.which("auditctl", path=COMMAND_PATH)

    if systemctl is None:
        errors.append("systemctl_unavailable")
    else:
        shown = run(
            systemctl,
            "show",
            "auditd.service",
            "--no-pager",
            "--property=" + SYSTEMD_PROPERTIES,
        )
        if shown.returncode != 0:
            errors.append("systemctl_show_failed:" + shown.stderr.strip()[:256])
        else:
            properties = parse_key_value(shown.stdout)
            event.update(
                service_load_state=properties.get("LoadState"),
                service_active_state=properties.get("ActiveState"),
                service_sub_state=properties.get("SubState"),
                service_result=properties.get("Result") or None,
                service_main_pid=integer(properties.get("MainPID")),
                service_unit_file_state=properties.get("UnitFileState"),
            )

    if auditctl is None:
        errors.append("auditctl_unavailable")
    else:
        status = run(auditctl, "-s")
        if status.returncode != 0:
            errors.append("auditctl_status_failed:" + status.stderr.strip()[:256])
        else:
            audit = parse_audit_status(status.stdout)
            for source_name, target_name in (
                ("enabled", "audit_enabled"),
                ("failure", "audit_failure"),
                ("pid", "audit_pid"),
                ("rate_limit", "audit_rate_limit"),
                ("backlog_limit", "audit_backlog_limit"),
                ("lost", "audit_lost"),
                ("backlog", "audit_backlog"),
                ("backlog_wait_time", "audit_backlog_wait_time"),
                ("backlog_wait_time_actual", "audit_backlog_wait_time_actual"),
            ):
                event[target_name] = audit.get(source_name)

    event["collector_status"] = "ok" if not errors else "error"
    event["collector_error"] = ";".join(errors) if errors else None
    print(json.dumps(event, separators=(",", ":"), sort_keys=True))


if __name__ == "__main__":
    main()
